BEGIN;SET LOCAL lock_timeout='5s';
DO $guard$ BEGIN
IF md5(pg_get_functiondef('private.bag_capacity(uuid)'::regprocedure))<>'c736d0b7b30568b1618ad48e51a08daf' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.bag_capacity(uuid)'::regprocedure) IS DISTINCT FROM NULL THEN RAISE EXCEPTION 'REWARD_PRESENTATION_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pass_daily_item_preview(jsonb)'::regprocedure))<>'974a09a86d7a472fe521f414786a0681' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pass_daily_item_preview(jsonb)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_PRESENTATION_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('private.oak_calendar_projection(uuid)'::regprocedure))<>'3e8649fe27f748612f15a2f4f0f651a7' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.oak_calendar_projection(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_PRESENTATION_SOURCE_OR_ACL_DRIFT';END IF;
IF (SELECT extra->'perks' FROM private.store_categories WHERE key='pass') IS DISTINCT FROM '["+25 bag space while active","Daily: 2 Berries, 1 Honey, 20 PokéCoins","Weekly: 5 Poké Balls, 3 Berries, 1 Poké Radar, 150 PokéCoins"]'::jsonb THEN RAISE EXCEPTION 'PASS_PERKS_COPY_DRIFT';END IF;
END $guard$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;
UPDATE private.store_categories SET extra=jsonb_set(coalesce(extra,'{}'),'{perks}','["Daily: one rotating item and 50 PokéCoins","Weekly: rotating supplies and 150 PokéCoins"]'::jsonb) WHERE key='pass';
COMMIT;
